package io.github.dream07code.innovationspace.points;import io.github.dream07code.innovationspace.member.MemberController;import io.github.dream07code.innovationspace.common.api.ApiResponse;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController public class PointsController{private final PointLedgerService points;private final RankingService rankings;public PointsController(PointLedgerService p,RankingService r){points=p;rankings=r;}@GetMapping("/api/v1/points/me")public ApiResponse<Map<String,Object>> me(){var p=MemberController.actor();return ApiResponse.success(Map.of("memberId",p.memberId().toString(),"totalPoints",points.total(p.memberId())));}@GetMapping("/api/v1/points/ledger")public ApiResponse<Map<String,Object>> ledger(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){var p=MemberController.actor();return ApiResponse.success(points.ledger(p.memberId(),page,size,p));}@GetMapping("/api/v1/rankings/overall")public ApiResponse<Map<String,Object>> overall(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(rankings.overall(page,size));}}
